1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		planID      string
20		terms       PlanTerms
21		activatedAt time.Time
22		// termsHistory 按生效月份升序记录每次换套餐后的条件；
23		// 首条为开通当月适用的开通快照。账单按账期从中取当时适用的条件。
24		termsHistory []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27		// cancelEnd 已安排的终止时刻（取消请求时刻的下一个 UTC 自然月月初）。
28		// 非 nil 且尚未到达时为等待取消状态；到达后本订阅段终止并移入 history。
29		cancelEnd *time.Time
30		// endedAt 已终止订阅段的实际终止时刻；当前有效段为 nil。
31		endedAt *time.Time
32	}
33	
34	type eventRecord struct {
35		at     time.Time
36		qty    int64
37		period Month
38	}
39	
40	type billRecord struct {
41		bill Bill
42	}
43	
44	type paymentRecord struct {
45		period Month
46		amount int64
47		// balance 与 settled 是本笔付款首次成功登记完成时账单的余额与付清状态。
48		// 完全相同的重报原样返回该历史结果，不随后续付款或账单当前状态变化。
49		balance int64
50		settled bool
51	}
52	
53	type account struct {
54		id       string
55		sub      *subRecord
56		history  []*subRecord
57		events   map[string]eventRecord
58		usage    map[Month]int64
59		bills    map[Month]*billRecord
60		payments map[string]paymentRecord
61	}
62	
63	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
64	func NewService() *Service {
65		return NewServiceWithClock(time.Now)
66	}
67	
68	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
69	func NewServiceWithClock(now func() time.Time) *Service {
70		if now == nil {
71			now = time.Now
72		}
73		return &Service{
74			now:      now,
75			accounts: make(map[string]*account),
76			plans:    make(map[string]Plan),
77		}
78	}
79	
80	func (s *Service) nowUTC() time.Time {
81		return s.now().UTC()
82	}
83	
84	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
85	func (s *Service) CreateAccount(id string) error {
86		if id == "" {
87			return invalidf("account id is empty")
88		}
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		if _, ok := s.accounts[id]; ok {
92			return ErrAccountExists
93		}
94		s.accounts[id] = &account{
95			id:       id,
96			events:   make(map[string]eventRecord),
97			usage:    make(map[Month]int64),
98			bills:    make(map[Month]*billRecord),
99			payments: make(map[string]paymentRecord),
100		}
101		return nil
102	}
103	
104	func validatePlan(p Plan) error {
105		if p.ID == "" {
106			return invalidf("plan id is empty")
107		}
108		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
109			return invalidf("plan %q has negative amount or quantity", p.ID)
110		}
111		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
112			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
113		}
114		return nil
115	}
116	
117	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
118	func (s *Service) CreatePlan(p Plan) error {
119		if err := validatePlan(p); err != nil {
120			return err
121		}
122		s.mu.Lock()
123		defer s.mu.Unlock()
124		if _, ok := s.plans[p.ID]; ok {
125			return ErrPlanExists
126		}
127		s.plans[p.ID] = p
128		return nil
129	}
130	
131	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
132	// 已开通订阅继续使用开通时保存的快照。
133	func (s *Service) UpdatePlan(p Plan) error {
134		if err := validatePlan(p); err != nil {
135			return err
136		}
137		s.mu.Lock()
138		defer s.mu.Unlock()
139		if _, ok := s.plans[p.ID]; !ok {
140			return ErrPlanNotFound
141		}
142		s.plans[p.ID] = p
143		return nil
144	}
145	
146	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
147	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
148	// 首月仍收完整月费并提供完整额度。
149	//
150	// 订阅终止（按月取消到达终止时刻）后可用本入口重新开通：activatedAt 不得早于
151	// 上一段订阅的终止时刻；重新开通保存当时的套餐条件，当月仍收完整月费、给完整
152	// 额度。重新开通不重置账户内事件与付款标识，也不清除旧欠费。
153	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
154		if accountID == "" {
155			return invalidf("account id is empty")
156		}
157		if planID == "" {
158			return invalidf("plan id is empty")
159		}
160		if activatedAt.IsZero() {
161			return invalidf("activated at is zero")
162		}
163		s.mu.Lock()
164		defer s.mu.Unlock()
165		acc, ok := s.accounts[accountID]
166		if !ok {
167			return ErrAccountNotFound
168		}
169		now := s.nowUTC()
170		// 与其他入口保持一致：先让已到期的换套餐/取消落入历史。
171		s.settleLocked(acc, now)
172		plan, ok := s.plans[planID]
173		if !ok {
174			return ErrPlanNotFound
175		}
176		if acc.sub != nil {
177			return ErrSubscriptionExists
178		}
179		activated := activatedAt.UTC()
180		// 重新开通时刻不得早于上一段订阅的终止时刻。
181		if n := len(acc.history); n > 0 {
182			if activated.Before(*acc.history[n-1].endedAt) {
183				return ErrResubscribeBeforeEnd
184			}
185		}
186		acc.sub = &subRecord{
187			planID:      planID,
188			terms:       termsOf(plan),
189			activatedAt: activated,
190			termsHistory: []termsEntry{{
191				effective: MonthOf(activated),
192				terms:     termsOf(plan),
193			}},
194		}
195		return nil
196	}
197	
198	// nextMonth 返回 period 的下一个 UTC 自然月。
199	func nextMonth(period Month) Month {
200		return MonthOf(period.End())
201	}
202	
203	// settleLocked 让当前订阅段中已到生效时刻的换套餐安排落入条件历史，
204	// 并在到达取消终止时刻时把当前段标记终止、移入 acc.history。
205	// 到达月初零点（或终止时刻）即生效，无需先上报用量或生成账单；即使中间若干月
206	// 没有调用服务，再次进入时也会在此一次性补齐。调用时持有 s.mu。
207	func (s *Service) settleLocked(acc *account, now time.Time) {
208		sub := acc.sub
209		if sub == nil {
210			return
211		}
212		current := MonthOf(now)
213		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
214			entry := termsEntry{
215				effective: sub.pending.EffectivePeriod,
216				terms:     sub.pending.Terms,
217			}
218			sub.termsHistory = append(sub.termsHistory, entry)
219			sub.planID = sub.pending.TargetPlanID
220			sub.terms = sub.pending.Terms
221			sub.pending = nil
222		}
223		if sub.cancelEnd != nil && !now.Before(*sub.cancelEnd) {
224			end := *sub.cancelEnd
225			sub.cancelEnd = nil
226			sub.pending = nil
227			sub.endedAt = &end
228			acc.history = append(acc.history, sub)
229			acc.sub = nil
230		}
231	}
232	
233	// activeSegmentAtLocked 返回覆盖时刻 at 的订阅段：activatedAt <= at < end。
234	// 优先检查当前段，再按时间倒序检查历史段。调用时持有 s.mu。
235	func activeSegmentAtLocked(acc *account, at time.Time) *subRecord {
236		if cur := acc.sub; cur != nil && !at.Before(cur.activatedAt) {
237			if cur.cancelEnd == nil || at.Before(*cur.cancelEnd) {
238				return cur
239			}
240		}
241		for i := len(acc.history) - 1; i >= 0; i-- {
242			h := acc.history[i]
243			if !at.Before(h.activatedAt) && at.Before(*h.endedAt) {
244				return h
245			}
246		}
247		return nil
248	}
249	
250	// termsForPeriod 在订阅段 sub 中返回指定账期当时适用的套餐条件快照。
251	// 条件历史按生效月份升序，取不晚于 period 的最后一条；
252	// 这样历史账单始终按该账期条件计算，不受后续换套餐影响。
253	func termsForPeriod(sub *subRecord, period Month) PlanTerms {
254		t := sub.termsHistory[0].terms
255		for _, e := range sub.termsHistory {
256			if period.Before(e.effective) {
257				break
258			}
259			t = e.terms
260		}
261		return t
262	}
263	
264	// segmentForBillingLocked 返回账期 period 应使用的订阅段：
265	// 该订阅段在该账期内确有覆盖（开通当月计入，终止当月不计入）。
266	// 完全无订阅覆盖的月份返回 nil。调用时持有 s.mu。
267	func segmentForBillingLocked(acc *account, period Month) *subRecord {
268		if cur := acc.sub; cur != nil && !period.Before(MonthOf(cur.activatedAt)) {
269			return cur
270		}
271		for i := len(acc.history) - 1; i >= 0; i-- {
272			h := acc.history[i]
273			if period.Before(MonthOf(h.activatedAt)) {
274				continue
275			}
276			if period.Before(MonthOf(*h.endedAt)) {
277				return h
278			}
279		}
280		return nil
281	}
282	
283	// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
284	//
285	// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
286	// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
287	// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
288	//
289	// 每个账户至多保留一条尚未生效的安排：再次安排同一目标套餐时返回原安排，
290	// 不重新取价（Created 为 false）；安排另一目标套餐则替换原安排，生效月份仍为
291	// 本次请求被接受时的下一月。欠费停用期间也可以安排。
292	//
293	// 账户不存在、尚未开通订阅、开通时刻尚未到达、目标套餐不存在、目标套餐与当前
294	// 生效套餐相同时请求失败，原有安排保持不变。登记取消订阅会清除尚未生效的安排，
295	// 等待取消期间安排换套餐失败（ErrPlanChangeWhileCancelling）。
296	func (s *Service) SchedulePlanChange(accountID, targetPlanID string) (PlanChangeResult, error) {
297		if accountID == "" {
298			return PlanChangeResult{}, invalidf("account id is empty")
299		}
300		if targetPlanID == "" {
301			return PlanChangeResult{}, invalidf("target plan id is empty")
302		}
303		s.mu.Lock()
304		defer s.mu.Unlock()
305	
306		acc, ok := s.accounts[accountID]
307		if !ok {
308			return PlanChangeResult{}, ErrAccountNotFound
309		}
310		now := s.nowUTC()
311		// 先让已到期的安排/取消生效：例如跨月后的首次调用，此时“当前套餐”已是新套餐；
312		// 恰在换套餐生效的月初登记取消，先承认该次切换，取消从再下一月生效。
313		s.settleLocked(acc, now)
314		if acc.sub == nil {
315			return PlanChangeResult{}, ErrSubscriptionNotFound
316		}
317		if now.Before(acc.sub.activatedAt) {
318			return PlanChangeResult{}, ErrSubscriptionNotActivated
319		}
320		if acc.sub.cancelEnd != nil {
321			return PlanChangeResult{}, ErrPlanChangeWhileCancelling
322		}
323	
324		plan, ok := s.plans[targetPlanID]
325		if !ok {
326			return PlanChangeResult{}, ErrPlanNotFound
327		}
328		if targetPlanID == acc.sub.planID {
329			return PlanChangeResult{}, ErrPlanChangeSamePlan
330		}
331	
332		// 已有安排且目标相同：原样返回，不重新取价。
333		if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
334			return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
335		}
336	
337		change := PlanChange{
338			TargetPlanID:    targetPlanID,
339			Terms:           termsOf(plan),
340			EffectivePeriod: nextMonth(MonthOf(now)),
341		}
342		acc.sub.pending = &change
343		return PlanChangeResult{Created: true, Change: change}, nil
344	}
345	
346	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
347	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
348	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
349	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
350	func (s *Service) CancelPlanChange(accountID string) error {
351		if accountID == "" {
352			return invalidf("account id is empty")
353		}
354		s.mu.Lock()
355		defer s.mu.Unlock()
356		acc, ok := s.accounts[accountID]
357		if !ok {
358			return ErrAccountNotFound
359		}
360		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
361		s.settleLocked(acc, s.nowUTC())
362		if acc.sub == nil {
363			return ErrSubscriptionNotFound
364		}
365		acc.sub.pending = nil
366		return nil
367	}
368	
369	// CancelSubscription 为当前有效订阅登记按月取消。
370	//
371	// 仅当订阅已生效（当前时刻不早于开通时刻）时可取消；欠费停用不妨碍取消，也不
372	// 免除债务。终止时刻为请求时刻的下一个 UTC 自然月月初零点（UTC）：当月照常
373	// 接收用量并按完整月费与额度计费，不按天退款。重复取消始终返回原终止时刻，
374	// 不把期限后移（Cancelled 为 false）。
375	//
376	// 成功时清除尚未生效的换套餐安排；若请求恰在某次换套餐生效的月初，先承认该次
377	// 切换，取消从再下一月生效。等待取消期间拒绝新的换套餐安排。
378	//
379	// 账户不存在、从未开通或当前无有效订阅、开通时刻尚未到达时请求失败。
380	func (s *Service) CancelSubscription(accountID string) (CancelSubscriptionResult, error) {
381		if accountID == "" {
382			return CancelSubscriptionResult{}, invalidf("account id is empty")
383		}
384		s.mu.Lock()
385		defer s.mu.Unlock()
386	
387		acc, ok := s.accounts[accountID]
388		if !ok {
389			return CancelSubscriptionResult{}, ErrAccountNotFound
390		}
391		now := s.nowUTC()
392		// 先补齐到期状态：恰在月初时先承认到期换套餐，终止时刻取再下一月。
393		s.settleLocked(acc, now)
394		if acc.sub == nil {
395			return CancelSubscriptionResult{}, ErrSubscriptionNotFound
396		}
397		if now.Before(acc.sub.activatedAt) {
398			return CancelSubscriptionResult{}, ErrSubscriptionNotActivated
399		}
400	
401		// 重复取消：原样返回原终止时刻，不后移期限。
402		if acc.sub.cancelEnd != nil {
403			return CancelSubscriptionResult{
404				Cancelled:    false,
405				Cancellation: SubscriptionCancellation{EndAt: *acc.sub.cancelEnd},
406			}, nil
407		}
408	
409		// 登记取消清除尚未生效的换套餐安排（撤回取消也不恢复它）。
410		acc.sub.pending = nil
411		end := nextMonth(MonthOf(now)).Start()
412		acc.sub.cancelEnd = &end
413		return CancelSubscriptionResult{
414			Cancelled:    true,
415			Cancellation: SubscriptionCancellation{EndAt: end},
416		}, nil
417	}
418	
419	// UndoCancelSubscription 在取消生效前撤回按月取消安排，撤回后订阅继续有效。
420	// 有效订阅没有取消安排时撤回也成功；撤回不恢复登记取消时被清除的换套餐安排。
421	// 终止时刻已到（订阅已终止）后撤回失败（ErrSubscriptionNotFound）；
422	// 账户不存在或从未开通时同样失败。
423	func (s *Service) UndoCancelSubscription(accountID string) error {
424		if accountID == "" {
425			return invalidf("account id is empty")
426		}
427		s.mu.Lock()
428		defer s.mu.Unlock()
429		acc, ok := s.accounts[accountID]
430		if !ok {
431			return ErrAccountNotFound
432		}
433		// 到达终止时刻后订阅已终止：撤回失败。
434		s.settleLocked(acc, s.nowUTC())
435		if acc.sub == nil {
436			return ErrSubscriptionNotFound
437		}
438		acc.sub.cancelEnd = nil
439		return nil
440	}
441	
442	// RecordEvent 上报一条用量事件。
443	//
444	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
445	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
446	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
447	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
448	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
449	// ErrEventConflict。
450	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
451	// 但此前已接收事件的完全相同重报始终成功。
452	func (s *Service) RecordEvent(e Event) (EventResult, error) {
453		if e.AccountID == "" {
454			return EventResult{}, invalidf("account id is empty")
455		}
456		if e.EventID == "" {
457			return EventResult{}, invalidf("event id is empty")
458		}
459		if e.Quantity < 0 {
460			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
461		}
462		if e.At.IsZero() {
463			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
464		}
465		at := e.At.UTC()
466	
467		s.mu.Lock()
468		defer s.mu.Unlock()
469	
470		acc, ok := s.accounts[e.AccountID]
471		if !ok {
472			return EventResult{}, ErrAccountNotFound
473		}
474	
475		now := s.nowUTC()
476		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
477		s.settleLocked(acc, now)
478	
479		// 从未开通订阅的账户没有任何订阅段。
480		if acc.sub == nil && len(acc.history) == 0 {
481			return EventResult{}, ErrSubscriptionNotFound
482		}
483	
484		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
485		// 之后也返回成功。
486		if prev, ok := acc.events[e.EventID]; ok {
487			if !prev.at.Equal(at) || prev.qty != e.Quantity {
488				return EventResult{}, ErrEventConflict
489			}
490			return EventResult{Accepted: false, Period: prev.period}, nil
491		}
492	
493		if at.After(now) {
494			return EventResult{}, ErrEventInFuture
495		}
496		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
497		if activeSegmentAtLocked(acc, at) == nil {
498			return EventResult{}, ErrEventBeforeSubscription
499		}
500	
501		period := MonthOf(at)
502		if _, billed := acc.bills[period]; billed {
503			return EventResult{}, ErrMonthBilled
504		}
505		if s.isSuspendedLocked(acc, now) {
506			return EventResult{}, ErrSuspended
507		}
508	
509		total, ok := addNonNeg(acc.usage[period], e.Quantity)
510		if !ok {
511			return EventResult{}, ErrOverflow
512		}
513		// 所有校验通过后才落库：失败不消耗事件标识。
514		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
515		acc.usage[period] = total
516		return EventResult{Accepted: true, Period: period}, nil
517	}
518	
519	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
520	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
521	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
522	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
523	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
524	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
525		if accountID == "" {
526			return Bill{}, invalidf("account id is empty")
527		}
528		if period.Month < time.January || period.Month > time.December {
529			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
530		}
531		s.mu.Lock()
532		defer s.mu.Unlock()
533	
534		acc, ok := s.accounts[accountID]
535		if !ok {
536			return Bill{}, ErrAccountNotFound
537		}
538		if existing, ok := acc.bills[period]; ok {
539			return existing.bill, nil
540		}
541	
542		now := s.nowUTC()
543		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
544		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
545		// 也不会被后来的订阅覆盖。
546		s.settleLocked(acc, now)
547	
548		if acc.sub == nil && len(acc.history) == 0 {
549			return Bill{}, ErrSubscriptionNotFound
550		}
551		if period.End().After(now) {
552			return Bill{}, ErrBillMonthNotEnded
553		}
554	
555		sub := segmentForBillingLocked(acc, period)
556		if sub == nil {
557			// 早于首段开通，或处于两段订阅之间的空档。
558			return Bill{}, ErrBillBeforeSubscription
559		}
560	
561		terms := termsForPeriod(sub, period)
562		bill, err := buildBill(accountID, period, terms, acc.usage[period])
563		if err != nil {
564			return Bill{}, err
565		}
566		acc.bills[period] = &billRecord{bill: bill}
567		return bill, nil
568	}
569	
570	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
571	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
572		if accountID == "" {
573			return Bill{}, invalidf("account id is empty")
574		}
575		s.mu.Lock()
576		defer s.mu.Unlock()
577		acc, ok := s.accounts[accountID]
578		if !ok {
579			return Bill{}, ErrAccountNotFound
580		}
581		rec, ok := acc.bills[period]
582		if !ok {
583			return Bill{}, ErrBillNotFound
584		}
585		return rec.bill, nil
586	}
