552		if err != nil || st.Suspended {
553			t.Fatalf("zero bill suspended: %+v %v", st, err)
554		}
555	}
556	
557	func TestSuspensionAndRecovery(t *testing.T) {
558		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
559		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
560		mustAccount(t, s, "a")
561		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
562			t.Fatal(err)
563		}
564		janEvent := Event{AccountID: "a", EventID: "j1", At: utc(2026, 1, 20, 0, 0), Quantity: 1}
565		if _, err := s.RecordEvent(janEvent); err != nil {
566			t.Fatal(err)
567		}
568	
569		clk.t = utc(2026, 2, 1, 0, 0)
570		if _, err := s.CreateBill("a", jan(2026)); err != nil {
571			t.Fatal(err)
572		}
573	
574		// 截止前正常接收 2 月用量。
575		clk.t = utc(2026, 2, 2, 0, 0)
576		febEvent := Event{AccountID: "a", EventID: "f1", At: utc(2026, 2, 2, 0, 0), Quantity: 1}
577		if _, err := s.RecordEvent(febEvent); err != nil {
578			t.Fatalf("event before due: %v", err)
579		}
580	
581		// 到达截止时刻仍有余额：停用。
582		clk.t = utc(2026, 2, 8, 0, 0)
583		st, _ := s.Status("a")
584		if !st.Suspended {
585			t.Fatalf("should be suspended: %+v", st)
586		}
587		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f2", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
588			t.Fatalf("new event while suspended: %v", err)
589		}
590		// 已接收事件的相同重报仍成功。
591		if r, err := s.RecordEvent(janEvent); err != nil || r.Accepted {
592			t.Fatalf("jan replay suspended: %+v %v", r, err)
593		}
594		if r, err := s.RecordEvent(febEvent); err != nil || r.Accepted {
595			t.Fatalf("feb replay suspended: %+v %v", r, err)
596		}
597	
598		// 部分付款仍欠费，继续停用。
599		if _, err := s.RecordPayment("a", "p1", jan(2026), 500); err != nil {
600			t.Fatal(err)
601		}
602		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f3", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
603			t.Fatalf("still suspended after partial pay: %v", err)
604		}
605	
606		// 结清后立即恢复；2 月账单尚未生成，新用量可继续累计。
607		if _, err := s.RecordPayment("a", "p2", jan(2026), 500); err != nil {
608			t.Fatal(err)
609		}
610		st, _ = s.Status("a")
611		if st.Suspended {
612			t.Fatalf("should resume: %+v", st)
613		}
614		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f3", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); err != nil {
615			t.Fatalf("event after resume: %v", err)
616		}
617		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != 2 {
618			t.Fatalf("feb usage = %d want 2", u.Total)
619		}
620	
621		// Status 中应能看到各月用量与账单余额。
622		if len(st.MonthlyUsage) != 2 || st.MonthlyUsage[0].Period != jan(2026) || st.MonthlyUsage[1].Period != feb(2026) {
623			t.Fatalf("monthly usage: %+v", st.MonthlyUsage)
624		}
625		if len(st.Bills) != 1 || st.Bills[0].Period != jan(2026) || st.Bills[0].Balance != 0 || !st.Bills[0].Settled {
626			t.Fatalf("bills: %+v", st.Bills)
627		}
628	}
629	
630	func TestOverflowLeavesNoTrace(t *testing.T) {
631		s, clk := newTestService(utc(2026, 2, 1, 0, 0))
632		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
633		mustAccount(t, s, "a")
634		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
635			t.Fatal(err)
636		}
637	
638		base := maxInt64 - 5
639		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "base", At: utc(2026, 1, 10, 0, 0), Quantity: base}); err != nil {
640			t.Fatal(err)
641		}
642		// 本次累计将溢出：失败且不消耗事件标识。
643		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "try", At: utc(2026, 1, 11, 0, 0), Quantity: 6}); !errors.Is(err, ErrOverflow) {
644			t.Fatalf("usage overflow: %v", err)
645		}
646		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != base {
647			t.Fatalf("usage after overflow = %d", u.Total)
648		}
649		// 同一标识以不溢出的数量重试，应当成功。
650		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "try", At: utc(2026, 1, 11, 0, 0), Quantity: 5}); err != nil {
651			t.Fatalf("id reused after overflow failure: %v", err)
652		}
653	
654		// 超额费用溢出：超额用量 maxInt64 * 单价 2。
655		mustAccount(t, s, "b")
656		mustPlan(t, s, Plan{ID: "p2", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 2, TaxRateBasisPoints: 0})
657		if err := s.Subscribe("b", "p2", utc(2026, 1, 1, 0, 0)); err != nil {
658			t.Fatal(err)
659		}
660		if _, err := s.RecordEvent(Event{AccountID: "b", EventID: "big", At: utc(2026, 1, 10, 0, 0), Quantity: maxInt64}); err != nil {
661			t.Fatal(err)
662		}
663		if _, err := s.CreateBill("b", jan(2026)); !errors.Is(err, ErrOverflow) {
664			t.Fatalf("overage overflow: %v", err)
665		}
666		if _, err := s.GetBill("b", jan(2026)); !errors.Is(err, ErrBillNotFound) {
667			t.Fatalf("partial bill left behind: %v", err)
668		}
669	
670		// 税额与月费之和溢出（月费 maxInt64，税率 100%）。
671		mustAccount(t, s, "c")
672		mustPlan(t, s, Plan{ID: "p3", MonthlyFee: maxInt64, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 10000})
673		if err := s.Subscribe("c", "p3", utc(2026, 1, 1, 0, 0)); err != nil {
674			t.Fatal(err)
675		}
676		if _, err := s.CreateBill("c", jan(2026)); !errors.Is(err, ErrOverflow) {
677			t.Fatalf("total overflow: %v", err)
678		}
679	
680		_ = clk
681	}
682	
683	func TestConcurrentDuplicates(t *testing.T) {
684		s, clk := newTestService(utc(2026, 2, 1, 0, 0))
685		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 5, OveragePrice: 10, TaxRateBasisPoints: 1000})
686		mustAccount(t, s, "a")
687		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
688			t.Fatal(err)
689		}
690		ev := Event{AccountID: "a", EventID: "dup", At: utc(2026, 1, 10, 0, 0), Quantity: 7}
691	
692		const n = 64
693		var wg sync.WaitGroup
694		var accepted int64
695		var mu sync.Mutex
696		wg.Add(n)
697		for i := 0; i < n; i++ {
698			go func() {
699				defer wg.Done()
700				r, err := s.RecordEvent(ev)
701				if err != nil {
702					t.Errorf("concurrent event: %v", err)
703					return
704				}
705				if r.Accepted {
706					mu.Lock()
707					accepted++
708					mu.Unlock()
709				}
710			}()
711		}
712		wg.Wait()
713		if accepted != 1 {
714			t.Fatalf("accepted = %d, want 1", accepted)
715		}
716		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 7 {
717			t.Fatalf("usage = %d, want 7", u.Total)
718		}
719	
720		// 并发出账只生成一张。
721		bills := make([]Bill, n)
722		wg.Add(n)
723		for i := 0; i < n; i++ {
724			go func(i int) {
725				defer wg.Done()
726				b, err := s.CreateBill("a", jan(2026))
727				if err != nil {
728					t.Errorf("concurrent bill: %v", err)
729					return
730				}
731				bills[i] = b
732			}(i)
733		}
734		wg.Wait()
735		var due int64 = -1
736		for _, b := range bills {
737			if due == -1 {
738				due = b.TotalDue
739			} else if b.TotalDue != due {
740				t.Fatalf("bills differ: %d vs %d", due, b.TotalDue)
741			}
742		}
743		// fee 1000 + overage (7-5)*10=20 => subtotal 1020, tax 102 => 1122
744		if due != 1122 {
745			t.Fatalf("due = %d, want 1122", due)
746		}
747	
748		// 并发同标识付款只扣一次。
749		var registered int64
750		wg.Add(n)
751		for i := 0; i < n; i++ {
752			go func() {
753				defer wg.Done()
754				r, err := s.RecordPayment("a", "pay", jan(2026), 1122)
755				if err != nil {
756					t.Errorf("concurrent pay: %v", err)
757					return
758				}
759				if r.Registered {
760					mu.Lock()
761					registered++
762					mu.Unlock()
763				}
764			}()
765		}
766		wg.Wait()
767		if registered != 1 {
768			t.Fatalf("registered = %d, want 1", registered)
769		}
770		b, _ := s.GetBill("a", jan(2026))
771		if b.Paid != 1122 || b.Balance != 0 || !b.Settled {
772			t.Fatalf("bill after concurrent pay: paid=%d bal=%d settled=%v", b.Paid, b.Balance, b.Settled)
773		}
774	
775		// 并发不同标识事件全部累计一次。
776		wg.Add(n)
777		for i := 0; i < n; i++ {
778			go func(i int) {
779				defer wg.Done()
780				_, err := s.RecordEvent(Event{
781					AccountID: "a",
782					EventID:   fmt.Sprintf("e%d", i),
783					At:        utc(2026, 2, 1, 0, 0),
784					Quantity:  1,
785				})
786				if err != nil {
787					t.Errorf("distinct event: %v", err)
788				}
789			}(i)
790		}
791		wg.Wait()
792		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != n {
793			t.Fatalf("feb usage = %d, want %d", u.Total, n)
794		}
795	
796		_ = clk
797	}
