200		}
201		// 停用再次拒绝新增用量；被拒用量不增加累计、不占用标识（同路径规则）。
202		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr-3", At: utc(2026, 4, 8, 0, 0), Quantity: 2}); !errors.Is(err, ErrSuspended) {
203			t.Fatalf("event exactly at mar due: %v", err)
204		}
205		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 9 {
206			t.Fatalf("apr usage = %d after due rejection, want 9", u.Total)
207		}
208		// 一月、二月已结清状态不被三月到期影响。
209		wantBill(t, s, jan(2026), janDue, 1000, 0, true)
210		wantBill(t, s, feb(2026), febDue, 1000, 0, true)
211		wantBill(t, s, mar(2026), marDue, 0, 1000, false)
212	}
