213		// 2 月用量按新套餐：25 单位 -> 超额 5 * 200 = 1000，月费 2000。
214		// 截止前付清 1 月账单，避免欠费停用。
215		if _, err := s.RecordPayment("u", "p", jan(2026), janBill.TotalDue); err != nil {
216			t.Fatal(err)
217		}
