	mustPlan(t, s, planDef("b", 2000, 20, 8, 600))
	mustAccount(t, s, "u")
	mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
	mustSchedule(t, s, "u", "b")

	// 1 月仍按旧套餐。
	st, _ := s.Status("u")
	if st.CurrentTerms.PlanID != "a" {
		t.Fatalf("jan current = %s", st.CurrentTerms.PlanID)
