	if st.CurrentTerms.PlanID != "b" || st.PendingChange != nil {
		t.Fatalf("feb current = %+v pending = %+v", st.CurrentTerms, st.PendingChange)
	}

	// 中间几个月不调用服务，4 月再访问仍得到正确当前套餐。
	clk.t = utc(2026, 4, 10, 9, 0)
